-- Classic 1.60: vanilla weapon damage for the weapons whose WoW Forever damage is not what the item level tables give.
-- The server works weapon damage out from the ItemDamage tables (item level, quality, slot). That matches Forever for
-- 2,056 of the 2,826 weapons compared (nearly every melee one), but Forever's bows, guns and crossbows hit for about 0.6
-- of the table, staves for about 0.74, caster one-handers for about 0.66, wands for 1.35-2.6 times it, and thrown weapons
-- got no damage at all (the server has no table for them). Forever's own new weapons follow the same pattern. Rows are the
-- Forever item page damage (Wowhead Forever); for the raid weapons Forever's client blanks, the Classic damage. Weapons not
-- listed keep the table damage. At another item level the damage follows the table by the same ratio. Loaded by
-- ObjectMgr::LoadClassicItemDamage.
CREATE TABLE IF NOT EXISTS `classic_item_damage` (
  `entry` int unsigned NOT NULL,
  `min_damage` float NOT NULL DEFAULT 0 COMMENT 'vanilla minimum weapon damage',
  `max_damage` float NOT NULL DEFAULT 0 COMMENT 'vanilla maximum weapon damage',
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Classic 1.60: vanilla weapon damage where it differs from the item level tables';

DELETE FROM `classic_item_damage`;
